	if got := ChangeSeatText("SKY123", ""); !strings.Contains(strings.ToLower(got), "which seat") {
		t.Errorf("ChangeSeatText(no seat) = %q, want which-seat prompt", got)
	}
	if got := ChangeSeatText(" bay777 ", " 20f "); got != "Seat updated to 20F for booking BAY777." {
		t.Errorf("ChangeSeatText update = %q", got)
	}
}

func TestChangeSeatCoordinates(t *testing.T) {
	cases := []struct {
		name  string
		input string
		want  string
	}{
		{"first seat", "1A", "1A"},
		{"last seat", "30F", "30F"},
		{"lowercase whitespace", " \t7c\n", "7C"},
		{"leading zeroes", "00024b", "24B"},
		{"long leading zeroes", strings.Repeat("0", 10000) + "9D", "9D"},
		{"zero", "0A", ""},
		{"zero padded", "00A", ""},
		{"row 31", "031a", ""},
		{"large row", "99A", ""},
		{"column G", "20G", ""},
		{"column Z", "99Z", ""},
		{"fullwidth", "１２Ａ", ""},
		{"fullwidth digits", "１２A", ""},
		{"fullwidth column", "12Ａ", ""},
		{"Arabic digits", "١٢A", ""},
		{"positive sign", "+12A", ""},
		{"negative sign", "-12A", ""},
		{"embedded space", "12 A", ""},
		{"embedded tab", "1\t2A", ""},
		{"extra suffix", "12AB", ""},
		{"decimal", "12.0A", ""},
		{"column only", "A", ""},
		{"row only", "12", ""},
		{"long digits", strings.Repeat("9", 10000) + "A", ""},
		{"long zero row", strings.Repeat("0", 10000) + "F", ""},
		{"long out of range", strings.Repeat("0", 10000) + "31F", ""},
	}
	for _, code := range []string{"SKY123", "BAY777"} {
		t.Run(code, func(t *testing.T) {
			for _, tc := range cases {
				t.Run(tc.name, func(t *testing.T) {
					preserveBookings(t)
					before := *bookings[code]
					got := ChangeSeatText(" "+strings.ToLower(code)+" ", tc.input)
					if tc.want == "" {
						assertSeatRejection(t, got, code, before.Seat, "Invalid seat")
						if *bookings[code] != before {
							t.Error("rejection changed booking state")
						}
						return
					}
					if got != "Seat updated to "+tc.want+" for booking "+code+"." {
						t.Errorf("unexpected success: %q", got)
					}
					want := before
					want.Seat = tc.want
					if *bookings[code] != want {
						t.Errorf("booking not canonically updated: %+v", bookings[code])
					}
				})
			}
		})
	}
}

func TestRegisteredSeatToolValidation(t *testing.T) {
	var change Tool
	for _, tool := range airlineTools() {
		if tool.Name == "change_seat" {
			change = tool
		}
	}
	if change.Execute == nil {
		t.Fatal("change_seat is not registered")
	}
	for _, code := range []string{"SKY123", "BAY777"} {
